// Definition for a binary tree node.
class TreeNode {
    int val;
    TreeNode left;
    TreeNode right;
    TreeNode(int val) { this.val = val; }
}

private TreeNode prev = null;

public void flatten(TreeNode root) {
    if (root == null) return;
    flatten(root.right);     // right first...
    flatten(root.left);      // ...then left (reverse preorder)
    root.right = prev;       // link to the already-built suffix
    root.left = null;        // sever the old left pointer
    prev = root;             // current node becomes the new head
}

public void flatten(TreeNode root) {
    if (root == null) return;
    Deque<TreeNode> stack = new ArrayDeque<>();
    stack.push(root);
    TreeNode prev = null;
    while (!stack.isEmpty()) {
        TreeNode curr = stack.pop();
        if (curr.right != null) stack.push(curr.right); // push right first...
        if (curr.left != null)  stack.push(curr.left);  // ...so left pops first
        if (prev != null) {
            prev.right = curr;   // string current onto the spine
            prev.left = null;    // clear left pointer
        }
        prev = curr;
    }
}

