public void flatten(TreeNode root) {
    TreeNode curr = root;
    while (curr != null) {
        if (curr.left != null) {
            TreeNode pred = curr.left;          // rightmost of left subtree
            while (pred.right != null) pred = pred.right;
            pred.right = curr.right;            // reattach old right subtree
            curr.right = curr.left;             // move left subtree to right
            curr.left = null;                   // clear left pointer
        }
        curr = curr.right;                      // step down the spine
    }
}

